// {{ACTOR_TITLE}}
// Generated by Local Codex for Generator Run {{GENERATOR_RUN_ID}}.
//
// Requirements:
{{REQUIREMENTS_COMMENT}}

import { Actor, log } from 'apify';
import { CheerioCrawler } from 'crawlee';

await Actor.init();

try {
    const input = (await Actor.getInput()) ?? {};
    const {
        startUrls = [],
        maxResults = 100,
        proxyConfiguration: proxyInput,
    } = input;

    if (!Array.isArray(startUrls) || startUrls.length === 0) {
        log.warning('No startUrls provided. Nothing to do.');
    } else {
        const proxyConfiguration = proxyInput
            ? await Actor.createProxyConfiguration(proxyInput)
            : undefined;

        let saved = 0;

        const crawler = new CheerioCrawler({
            proxyConfiguration,
            maxRequestsPerCrawl: maxResults > 0 ? maxResults : undefined,
            async requestHandler({ request, $, log: crawlerLog }) {
                const item = {
                    url: request.loadedUrl ?? request.url,
                    title: $('title').first().text().trim() || null,
                    scrapedAt: new Date().toISOString(),
                };

                await Actor.pushData(item);
                saved += 1;
                crawlerLog.info(`Saved item ${saved}`, { url: item.url });
            },
            failedRequestHandler({ request }, error) {
                log.error(`Request failed: ${request.url}`, { message: error.message });
            },
        });

        await crawler.run(startUrls);
        log.info(`Finished. Saved ${saved} item(s) to the default dataset.`);
    }
} catch (error) {
    log.exception(error, 'Actor failed');
    // Actor.fail() exits with a non-zero code so the run is marked FAILED. (Actor.exit() in a finally block would exit 0.)
    await Actor.fail(String(error.message).slice(0, 500));
}

await Actor.exit();
